questions.question:
What is the output of the following C program?

#include <stdio.h>
void modify(int **pp) {
    static int val = 50;
    *pp = &val;
}
int main(void) {
    int x = 10;
    int *p = &x;
    modify(&p);
    printf("%d", *p);
    return 0;
}

What is the output of the following C code?

#include <stdio.h>
int main(void) {
    int a[] = {1, 2, 3, 4, 5};
    int *p = (int*)(&a + 1);
    printf("%d", *(p - 1));
    return 0;
}

